const articles = $input.all().filter(item => item.json.id);

if (articles.length === 0) {
  throw new Error('No approved articles found. Brett needs to approve articles in Telegram first.');
}

// Sort by composite_score descending
articles.sort((a, b) => 
  parseFloat(b.json.composite_score || 0) - parseFloat(a.json.composite_score || 0)
);

// Select template based on article count and scores
let template = 'standard_daily'; // Template A: 2 stories, 5 min
let templateLabel = 'Standard Daily (5 min)';

if (articles.length === 1) {
  template = 'deep_dive';
  templateLabel = 'Deep Dive (10 min)';
} else if (articles.length >= 5) {
  template = 'weekly_roundup';
  templateLabel = 'Weekly Roundup (15 min)';
}

// For standard daily, pick top 2; for deep dive, pick 1; for roundup, pick up to 7
let selected;
if (template === 'standard_daily') {
  selected = articles.slice(0, 2);
} else if (template === 'deep_dive') {
  selected = articles.slice(0, 1);
} else {
  selected = articles.slice(0, 7);
}

// Build prompt context
const combined = selected.map((item, i) => {
  return `Article ${i+1}: ${item.json.title}
Category: ${item.json.score_category || item.json.category || 'general'}
Score: ${item.json.composite_score}/10
Relevance: ${item.json.relevance_score}/10 | Novelty: ${item.json.novelty_score}/10
Content: ${(item.json.content || item.json.title).substring(0, 800)}`;
}).join('\n\n---\n\n');

// Pass article IDs for later marking as used
const articleIds = selected.map(a => a.json.id);

return [{
  json: {
    allArticles: combined,
    articleCount: selected.length,
    template,
    templateLabel,
    articleIds,
    articleTitles: selected.map(a => a.json.title)
  }
}];

// Get the article IDs from the selection step
const articleIds = $('Select Articles & Template').item.json.articleIds;
const script = $('Basic LLM Chain').item.json.text;

// Return each article ID as a separate item for the Supabase update
return articleIds.map(id => ({
  json: { id, status: 'used', script_length: script.length }
}));

